131	/* 今日日期戳 YYYYMMDD（本地时区，对时链路已闭环） */
132	static int today_stamp(void)
133	{
134	    time_t t = time(NULL);
135	    struct tm tm;
136	    localtime_r(&t, &tm);
137	    return (tm.tm_year + 1900) * 10000 + (tm.tm_mon + 1) * 100 + tm.tm_mday;
138	}
