144	/* 坐下：双计时按当前档位起点启动 */
145	static void health_session_start(void)
146	{
147	    int hot = (g_weather.cur_temp >= CFG_I("water_hot_temp_c", WATER_HOT_TEMP_C)) ? 1 : 0;
148	
149	    g_seated = true;
150	    g_water_level = 0;
151	    g_water_total_s = hot ? CFG_I("water_hot_l1_s", WATER_HOT_L1_S)
152	                          : CFG_I("water_l1_s", WATER_L1_S);
153	    g_water_remain_s = g_water_total_s;
154	    g_sit_level = 0;
155	    g_sit_total_s = CFG_I("sit_l1_s", SIT_L1_S);
156	    g_sit_remain_s = CFG_I("sit_l1_s", SIT_L1_S);
157	
158	    LV_LOG_USER("[health] seated, water=%ds(%s), sit=%ds",
159	                g_water_total_s, hot ? "hot" : "normal", g_sit_total_s);
160	    health_evt(DM_HEALTH_EVT_PRESENCE, 1);
161	    health_evt(DM_HEALTH_EVT_RING, 0);
162	}
163	
164	/* 离开：清零重来（用户拍板），弹窗收起 */
165	static void health_session_end(void)
166	{
167	    g_seated = false;
168	    g_water_level = 0;
169	    g_sit_level = 0;
170	    g_water_remain_s = 0;
171	    g_sit_remain_s = 0;
172	
173	    LV_LOG_USER("[health] left, session cleared");
174	    health_evt(DM_HEALTH_EVT_PRESENCE, 0);
175	    health_evt(DM_HEALTH_EVT_DISMISS, 0);   /* 收水窗 */
176	    health_evt(DM_HEALTH_EVT_DISMISS, 1);   /* 收坐窗 */
177	    health_evt(DM_HEALTH_EVT_RING, 0);
178	}
