180	/****************************************************************************
181	 * 状态机（1s tick）
182	 ****************************************************************************/
183	
184	static void health_tick_cb(lv_timer_t *timer)
185	{
186	    (void)timer;
187	
188	    /* 跨天：清零今日计数并保存 */
189	    int day = today_stamp();
190	    if (g_state_day == 0)
191	        g_state_day = day;
192	    else if (day != g_state_day)
193	    {
194	        g_state_day = day;
195	        g_water_count_today = 0;
196	        g_stand_count_today = 0;
197	        g_seat_today_s = 0;
198	        health_state_save();
199	        LV_LOG_USER("[health] new day %d, counters reset", day);
200	    }
201	
202	    /* ── 在座感知（prox 判据 + 防抖）── */
203	    int prox = dm_prox_get_cm();
204	    if (prox < 0)
205	    {
206	        /* 传感器不可用：回退纯计时模式（视为始终在座），日志一次 */
207	        if (!g_prox_fallback)
208	        {
209	            g_prox_fallback = true;
210	            LV_LOG_WARN("[health] prox sensor unavailable, fallback seated");
211	        }
212	        if (!g_seated)
213	            health_session_start();
214	    }
215	    else
216	    {
217	        if (prox <= CFG_I("prox_seat_cm", PROX_SEAT_CM))
218	        {
219	            g_absent_cnt = 0;
220	            if (!g_seated)
221	            {
222	                if (++g_seat_cnt >= CFG_I("prox_seat_debounce_s", PROX_SEAT_DEBOUNCE_S))
223	                {
224	                    g_seat_cnt = 0;
225	                    health_session_start();
226	                }
227	            }
228	        }
229	        else
230	        {
231	            g_seat_cnt = 0;
232	            if (g_seated)
233	            {
234	                if (++g_absent_cnt >= CFG_I("prox_absent_debounce_s", PROX_ABSENT_DEBOUNCE_S))
235	                {
236	                    g_absent_cnt = 0;
237	                    health_session_end();
238	                }
239	            }
240	        }
241	    }
242	
243	    /* 每秒 RING（含未在座）：双圈/健康卡/prox debug 实时刷新——
244	     * 2026-08-15：prox 调试显示不依赖坐下，RING 提前到 g_seated 判断前 */
245	    health_evt(DM_HEALTH_EVT_RING, 0);
246	
247	    /* ── 在座时：累计 + 双提醒倒计时 ── */
248	    if (!g_seated)
249	        return;
250	
251	    g_seat_today_s++;
252	
253	    /* 喝水：未触发时倒计时；触发后等按钮（remain=0 停住） */
254	    if (g_water_remain_s > 0)
255	    {
256	        g_water_remain_s--;
257	        if (g_water_remain_s == 0)
258	        {
259	            g_water_level++;
260	            LV_LOG_USER("[health] water popup L%d", g_water_level);
261	            health_evt(DM_HEALTH_EVT_WATER_POP, g_water_level);
262	        }
263	    }
264	
265	    /* 久坐 */
266	    if (g_sit_remain_s > 0)
267	    {
268	        g_sit_remain_s--;
269	        if (g_sit_remain_s == 0)
270	        {
271	            g_sit_level++;
272	            LV_LOG_USER("[health] sit popup L%d", g_sit_level);
273	            health_evt(DM_HEALTH_EVT_SIT_POP, g_sit_level);
274	        }
275	    }
276	
277	    /* 每分钟落盘一次在座秒（计数变化即时存） */
278	    if (g_seat_today_s % 60 == 0)
279	        health_state_save();
280	}
