598	static int lv_demo_update_sensor_data(lv_demo_sensor_select_t sensors_to_update, void *ctx) {
599	    LV_UNUSED(ctx); /* 如果不需要上下文，可以忽略 */
600	    if (!sensor_sub.initialized) {
