613	        return 0;
614	    }
615	    int ret = poll(sensor_sub.fds, LV_DEMO_POLLFD_NUM, 100);
616	    if (ret < 0) {
617	        LV_LOG_ERROR("Failed to poll sensor data: %d", ret);
618	        return -1;
619	    }
