640	    if ((sensors_to_update & LV_DEMO_UPDATE_HUMIDITY) &&
641	        (sensor_sub.humidity_sub >= 0) &&
642	        (sensor_sub.fds[1].revents & POLLIN)) {
643	        struct sensor_humi humi_data;
644	        if (orb_copy(ORB_ID(sensor_humi), sensor_sub.humidity_sub, &humi_data) == OK) {
645	            /* 直接更新全局湿度主题 */
646	            lv_subject_set_int(&humidity_subject, (int)(humi_data.humidity * 10));
647	            LV_LOG_INFO("Humidity updated: %.1f%%", humi_data.humidity);
648	            updated++;
649	        } else {
650	            LV_LOG_WARN("Failed to copy humidity data");
651	        }
