313	static int ltr553_thread(int argc, char **argv) {
314	  FAR struct ltr553_dev_s *priv;
315	  struct sensor_light light;
316	  struct sensor_prox prox;
317	  uint16_t ch0_data = 0, ch1_data = 0, ps_data = 0;
318	  uint8_t status = 0;
319	  int ret;
320	
321	  priv = g_ltr553_dev;
322	
323	  if (priv == NULL || priv->i2c == NULL) {
324	    return -EINVAL;
325	  }
326	
327	  while (true) {
328	    if (!priv->enabled) {
329	      ret = nxsem_wait(&priv->run);
330	      if (ret < 0) {
331	        break;
332	      }
333	    }
334	
335	    if (g_ltr553_dev == NULL || !priv->enabled) {
336	      continue;
337	    }
338	
339	    /* 读取组合状态寄存器 */
340	    ret = ltr553_get_reg8(priv, LTR553_ALS_PS_STATUS, &status);
341	    if (ret < 0) {
342	      continue;
343	    }
344	
345	    /* 读取ALS数据 */
346	    if (priv->sensors[LTR553_SENSOR_ALS].enabled) {
347	      /* 始终读取ALS数据*/
348	      ret = ltr553_get_reg16(priv, LTR553_ALS_DATA_CH0_0, &ch0_data);
349	      if (ret >= 0) {
350	        ret = ltr553_get_reg16(priv, LTR553_ALS_DATA_CH1_0, &ch1_data);
351	        if (ret >= 0) {
352	          /* 强制计算勒克斯值 */
353	          if (ch0_data > 0) {
354	            float ratio = (float)ch1_data / (float)ch0_data;
355	            if (ratio < 0.45f) {
356	              priv->lux = (1.7743f * ch0_data) + (1.1059f * ch1_data);
357	            } else if (ratio < 0.64f) {
358	              priv->lux = (4.2785f * ch0_data) - (1.9548f * ch1_data);
359	            } else if (ratio < 0.85f) {
360	              priv->lux = (0.5926f * ch0_data) - (0.1185f * ch1_data);
361	            } else {
362	              priv->lux = 0.0f;
363	            }
364	
365	            if (priv->lux < 0) {
366	              priv->lux = 0.0f;
367	            }
368	          } else {
369	            priv->lux = 0.0f;
370	          }
371	        }
372	      }
373	
374	      /* 推送ALS数据 */
375	      light.timestamp = sensor_get_timestamp();
376	      light.light = priv->lux;
377	
378	      if (priv->sensors[LTR553_SENSOR_ALS].lower.push_event != NULL) {
379	        priv->sensors[LTR553_SENSOR_ALS].lower.push_event(
380	            priv->sensors[LTR553_SENSOR_ALS].lower.priv, &light,
381	            sizeof(struct sensor_light));
382	
383	        /* 增强显示 - 显示计算过程 */
384	        int lux_int = (int)priv->lux;
385	        int lux_frac = (int)((priv->lux - lux_int) * 100 + 0.5f);
386	        sninfo("LTR553: ALS : %d.%02d lux (CH0=%d, CH1=%d)\n", lux_int, lux_frac,
387	              ch0_data, ch1_data);
388	      }
389	    }
390	
391	    /* 读取PS数据 */
392	    if (priv->sensors[LTR553_SENSOR_PS].enabled) {
393	      ret = ltr553_get_reg16(priv, LTR553_PS_DATA_0, &ps_data);
394	      if (ret >= 0) {
395	        /* 计算距离 */
396	        if (ps_data > 1000) {
397	          priv->proximity = 0.0f; /* 很近 */
398	        } else if (ps_data > 500) {
399	          priv->proximity = 1.0f; /* 近 */
400	        } else if (ps_data > 100) {
401	          priv->proximity = 5.0f; /* 中等距离 */
402	        } else if (ps_data > 10) {
403	          priv->proximity = 10.0f; /* 远 */
404	        } else {
405	          priv->proximity = 20.0f; /* 很远或无物体 */
406	        }
407	      } else {
408	        priv->proximity = -1.0f;
409	      }
410	
411	      /* 推送PS数据 */
412	      prox.timestamp = sensor_get_timestamp();
413	      prox.proximity = priv->proximity;
414	
415	      if (priv->sensors[LTR553_SENSOR_PS].lower.push_event != NULL) {
416	        priv->sensors[LTR553_SENSOR_PS].lower.push_event(
417	            priv->sensors[LTR553_SENSOR_PS].lower.priv, &prox,
418	            sizeof(struct sensor_prox));
419	
420	        if (priv->proximity >= 0) {
421	          int prox_int = (int)priv->proximity;
422	          int prox_frac = (int)((priv->proximity - prox_int) * 100 + 0.5f);
423	          sninfo("LTR553: PS : %d.%02d cm (Raw=%d)\n", prox_int, prox_frac,
424	                ps_data);
425	        }
426	      }
427	    }
428	
429	    /* 延时后继续轮询 */
430	    nxsig_usleep(CONFIG_SENSORS_LTR553_POLL_INTERVAL);
431	  }
432	
433	  return OK;
434	}
