/* P103：config 无任何 backend（未 set_llm/未配置 router）时，用
 * llm_proxy 的默认配置兜底注册 backend[0]——agent_secrets.h 注入的
 * 火山方舟 key/model（与 llm_proxy_init 同源），避免
 * "No available backend" 导致 LLM 调用直接失败。 */
if (s_backend_count == 0) {
    llm_backend_t* b = &s_backends[0];
    memset(b, 0, sizeof(*b));
    strncpy(b->host, AGENT_LLM_API_HOST, sizeof(b->host) - 1);
    strncpy(b->path, AGENT_LLM_API_PATH, sizeof(b->path) - 1);
    strncpy(b->port, "443", sizeof(b->port) - 1);
    if (AGENT_SECRET_API_KEY[0]) {
        strncpy(b->api_key, AGENT_SECRET_API_KEY, sizeof(b->api_key) - 1);
    }
    if (AGENT_SECRET_MODEL[0]) {
        strncpy(b->model, AGENT_SECRET_MODEL, sizeof(b->model) - 1);
    } else {
        strncpy(b->model, AGENT_LLM_DEFAULT_MODEL, sizeof(b->model) - 1);
    }
    b->priority = 0;
    b->cost_tier = 1;
    b->enabled = true;
    b->fail_count = 0;
    s_backend_count = 1;
    syslog(LOG_INFO, "[%s] P103: defaulted backend 0 to llm_proxy config (%s)\n",
        TAG, b->model);
}

