236	    int* out_status)
237	{
238	    /* Snapshot config under lock */
239	    char api_key[128], llm_host[128], llm_path[128], llm_port[8], model[64];
240	    pthread_mutex_lock(&s_llm_lock);
241	    memcpy(api_key, s_api_key, sizeof(api_key));
242	    memcpy(llm_host, s_llm_host, sizeof(llm_host));
243	    memcpy(llm_path, s_llm_path, sizeof(llm_path));
244	    memcpy(llm_port, s_llm_port, sizeof(llm_port));
245	    memcpy(model, s_model, sizeof(model));
246	    pthread_mutex_unlock(&s_llm_lock);
247	
248	    /* Allocate the response buffer once and hand it directly to the
249	     * TLS layer.  Previously we allocated a separate raw_buf and then
250	     * copied into resp_buf — doubling peak memory usage.  Now the
251	     * resp_buf IS the raw buffer, eliminating the copy. */
252	    size_t raw_cap = AGENT_LLM_STREAM_BUF_SIZE;
253	    if (resp_buf_init(rb, raw_cap) != OK)
254	        return ERROR;
255	
256	    /* OpenAI-compatible format: Authorization: Bearer <key> */
257	    char auth_header[256];
258	    snprintf(auth_header, sizeof(auth_header), "Bearer %s", api_key);
259	
260	    /* Extract provider ID from model string (e.g. "xiaomi/mimo-claw-0301" →
261	     * "xiaomi") Mify gateway requires X-Model-Provider-Id header for routing. */
262	    char provider[64] = { 0 };
263	    const char* slash = strchr(model, '/');
264	    if (slash) {
265	        size_t plen = (size_t)(slash - model);
266	        if (plen >= sizeof(provider))
267	            plen = sizeof(provider) - 1;
268	        memcpy(provider, model, plen);
269	    }
270	
271	    vela_header_t hdrs[] = { { "Authorization", auth_header },
272	        { provider[0] ? "X-Model-Provider-Id" : NULL,
273	            provider[0] ? provider : NULL },
274	        { NULL, NULL } };
275	
276	    int status;
277	    int use_tls = (strcmp(llm_port, "443") == 0);
278	
279	    if (use_tls) {
280	        status = vela_https_post_json(llm_host, llm_port, llm_path, hdrs, post_data,
281	            rb->data, raw_cap);
282	    } else {
283	        status = vela_http_post_json(llm_host, llm_port, llm_path, hdrs, post_data,
