    int gain = (g_music_volume * 32768) / 100;
    for (i = 0; i < ns; i++)
    {
        int v = p16[i];
        v = (v * gain) >> 15;
        /* P103 软限幅：解码/重采样输出副歌可达满幅（raw_peak=32767，
         * 日志实证），线性衰减后仍会顶格硬削波 → 破音/发沙。
         * 对 |v|>30000 的峰值做折线压缩（斜率 1/4，近似 tanh），
         * 保留动态但削去硬顶，改善听感。 */
        if (v > 30000)
            v = 30000 + (v - 30000) / 4;
        else if (v < -30000)
            v = -30000 - (v + 30000) / 4;
        ((int16_t *)out)[i] = (int16_t)v;
    }
}

